import React, { useEffect, useMemo, useState } from 'react';
import { io } from 'socket.io-client';
import { api, normalizeArrayPayload, normalizeTrades, badgeClass } from '../services/api';

const SOCKET_URL = 'http://localhost:5000';

export default function TransactionsPage() {
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const [trades, setTrades] = useState([]);
  const [riskLogs, setRiskLogs] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadAll = async () => {
    try {
      const [tradeRes, logRes] = await Promise.all([
        api.fetchTrades(page, 50),
        api.fetchRiskLogs(),
      ]);
      const logs = normalizeArrayPayload(logRes);
      const merged = normalizeTrades(normalizeArrayPayload(tradeRes), logs);
      setTrades(merged);
      setRiskLogs(logs);
      setLoading(false);
    } catch (err) {
      console.error(err);
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAll();
    const id = setInterval(loadAll, 2000);
    const socket = io(SOCKET_URL, { transports: ['websocket', 'polling'] });
    socket.on('fraud_alert', loadAll);
    socket.on('fraud_detected', loadAll);
    socket.on('risk_log', loadAll);
    socket.on('trade_inserted', loadAll);

    return () => {
      clearInterval(id);
      socket.disconnect();
    };
  }, [page]);

  const filtered = useMemo(() => {
    const q = search.toLowerCase().trim();
    return trades.filter((t) =>
      !q ||
      String(t.symbol || '').toLowerCase().includes(q) ||
      String(t.seller_name || `T${t.seller_id}`).toLowerCase().includes(q) ||
      String(t.buyer_name || `T${t.buyer_id}`).toLowerCase().includes(q) ||
      String(t.trade_id).includes(q)
    );
  }, [trades, search]);

  return (
    <div className="page-wrap grid-bg">
      <div className="page-container">
        <div style={{ marginBottom: 24 }}>
          <h1 style={{ fontSize: 28, fontWeight: 900, margin: 0 }}>
            Transaction <span className="neon-strong">Log</span>
          </h1>
          <div style={{ color: '#838b7d', marginTop: 8, fontSize: 16 }}>
            Live transaction risk analysis with instant score updates
          </div>
        </div>

        <div className="glass-strong" style={{ padding: 18, marginBottom: 18 }}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr auto auto', gap: 12, alignItems: 'center' }}>
            <input
              className="search-input"
              placeholder="Filter by trade id, stock, seller or buyer..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
            <div className="tag">{filtered.length} trades on this page</div>
            <div style={{ display: 'flex', gap: 8 }}>
              <button className="btn-outline" onClick={() => setPage((p) => Math.max(1, p - 1))}>← Prev</button>
              <div style={{ display: 'grid', placeItems: 'center', minWidth: 80, color: '#88907f', fontWeight: 700 }}>
                Page {page}
              </div>
              <button className="btn-outline" onClick={() => setPage((p) => p + 1)}>Next →</button>
            </div>
          </div>
        </div>

        <div className="glass-strong" style={{ overflow: 'hidden' }}>
          {loading ? (
            <div className="empty-state">Loading transaction feed...</div>
          ) : (
            <div style={{ overflowX: 'auto' }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Stock</th>
                    <th>Seller</th>
                    <th>Buyer</th>
                    <th>Price</th>
                    <th>Qty</th>
                    <th>Risk</th>
                    <th>Reason</th>
                    <th>Time</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((t) => (
                    <tr key={t.trade_id}>
                      <td style={{ color: '#7c8578', fontFamily: 'monospace' }}>#{t.trade_id}</td>
                      <td><span className="neon" style={{ fontWeight: 800 }}>{t.symbol || `#${t.stock_id}`}</span></td>
                      <td>{t.seller_name || `T${t.seller_id}`}</td>
                      <td>{t.buyer_name || `T${t.buyer_id}`}</td>
                      <td>${Number(t.price || 0).toFixed(2)}</td>
                      <td>{Number(t.quantity || 0)}</td>
                      <td><span className={badgeClass(t.risk_score)}>{t.risk_score || 0}</span></td>
                      <td style={{ minWidth: 240, color: '#95a08e' }}>{t.risk_reason || 'No suspicious pattern detected'}</td>
                      <td style={{ color: '#7f8879' }}>{t.timestamp ? new Date(t.timestamp).toLocaleString() : '—'}</td>
                    </tr>
                  ))}
                  {!filtered.length && (
                    <tr>
                      <td colSpan="9">
                        <div className="empty-state">No transactions on this page yet.</div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <div style={{ color: '#67705f', marginTop: 12, fontSize: 12 }}>
          Risk values are merged from live trades and `risk_log`, so the table updates without refresh.
        </div>
      </div>
    </div>
  );
}
